/* ---------- trading core ---------- */
const val=p=>{const t=DB[p.id];if(p.kind==='token')return p.qty*t.p;const d=p.side==='long'?1:-1;return Math.max(0,p.margin*(1+p.lev*d*(t.p/p.entry-1)))};
