/* profile */
function series(range){const n=70,end=total();const mul={'24h':1,'7d':1.8,'30d':2.6,All:3.4}[range];const delta=d24()*mul;const start=end-delta;const r=rng(hash(range+S.user.username));const a=[];for(let i=0;i<n;i++){const f=i/(n-1);const noise=(r()-.5)*Math.max(Math.abs(delta),.02)*.5*Math.sin(f*Math.PI);a.push(start+(end-start)*Math.pow(f,1.6)+noise)}a[n-1]=end;return {a,delta}}
function chartSvg(a,up){const mn=Math.min(...a),mx=Math.max(...a),w=400,h=130,pd=12;const pts=a.map((v,i)=>[i/(a.length-1)*w,h-pd-(mx===mn?.5:(v-mn)/(mx-mn))*(h-pd*2)]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');const c=up?'#2fe27a':'#ff5a3c';const l=pts[pts.length-1];return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="g${up?1:0}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${c}" stop-opacity=".25"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></linearGradient></defs><path d="${d}L${w} ${h}L0 ${h}Z" fill="url(#g${up?1:0})"/><path d="${d}" fill="none" stroke="${c}" stroke-width="2" vector-effect="non-scaling-stroke"/><circle cx="${l[0]-4}" cy="${l[1]}" r="4" fill="${c}"/></svg>`}
function posRow(p){const t=DB[p.id]||{sym:p.id,id:p.id};const v=val(p),c=cost(p),pc=(v/c-1)*100;const sub=p.kind==='perp'?`${levChip(p.side,p.lev)}`:`${abbr(p.qty)} ${esc(t.sym)}`;
return `<div class="row" data-act="token" data-id="${esc(p.id)}">${ico(t,42)}<div class="mid"><div class="nm">${esc(t.name||t.sym)}</div><div class="sub">${sub}</div></div><div class="rt"><div class="px" data-pv="${p.uid}">${usd(v)}</div><div class="ch ${pc<0?'dn':'up'}" data-pp="${p.uid}">${pct(pc)}</div></div></div>`}
