const row=(go,icon,title,r,d)=>`<button class="set" data-go="${go}"><span class="lead">${I(icon,20)}</span><span class="g"><div class="t">${title}</div>${d?`<div class="d">${d}</div>`:''}</span>${r?`<span class="r">${r}</span>`:''}${I('chev',15)}</button>`;
const tgl=(k,t,d,on)=>`<div class="set"><div class="g"><div class="t">${t}</div>${d?`<div class="d">${d}</div>`:''}</div>${sw(k,on)}</div>`;
const sub=(title,body,back)=>`<div class="page"><div class="hd"><button class="ibtn" data-act="back">${I('back',22)}</button><h1>${title}</h1><span class="sp"></span></div>${body}</div>`;
const FAQ=[['How do I deposit?','Open Deposit from Home or Profile, choose a method, enter an amount. In this demo, deposits are simulated and credit your Tokens cash instantly.'],['What is Transfer cash?','Tokens and Perps use separate cash pools. Transfer cash moves money between them.'],['How is perp PnL calculated?','PnL = margin × leverage × price change, in the direction of your Long or Short. If your position value reaches $0 it is liquidated.'],['Is this real money?','No. This is a prototype with simulated markets and balances. Nothing here moves real funds.']];
function pgSettings(r){const [a,b]=r;
if(!a)return `<div class="page"><div class="hd"><button class="ibtn" data-act="back">${I('back',22)}</button><span style="flex:1"></span></div><h2 class="pt">${t_('settings')}</h2><div>${row('settings/profile','user',t_('acct'))}${row('settings/appearance','sl',t_('appear'))}${row('settings/language','globe',t_('lang'),S.lang==='system'?'System':LANGS.find(l=>l[0]===S.lang)[1])}${row('settings/notifications','bell',t_('notif'))}${row('settings/security','shield',t_('sec'))}<button class="set" data-act="depwd"><span class="lead">${I('bank',20)}</span><span class="g"><div class="t">${t_('dep')}</div></span>${I('chev',15)}</button>${row('settings/legal','scale',t_('legal'))}${row('settings/taxes','file',t_('tax'))}${row('settings/help','help',t_('help'))}<button class="set" data-act="discord"><span class="lead">${I('disc',20)}</span><span class="g"><div class="t">Discord</div></span>${I('chev',15)}</button><button class="set" data-act="logout" style="color:var(--dn)"><span>${I('out',20)}</span><span class="g"><div class="t">${t_('logout')}</div></span></button></div><div class="dim" style="padding:20px 16px;font-size:11px">v1.0.0 · demo build</div></div>`;
if(a==='profile'){const u=S.user;return sub('Edit profile',`<div class="pad"><div style="position:relative"><div class="ban" style="height:96px;border-radius:12px;background-image:url(${u.banner||IMG.BANNER})"></div><div style="position:absolute;right:8px;top:8px;display:flex;gap:6px"><button class="ibtn" style="background:rgba(0,0,0,.5);color:#fff;width:30px;height:30px" data-act="pickBanner">${I('pen',14)}</button></div><button class="pav" style="position:absolute;left:6px;bottom:-34px;width:64px;height:64px;margin:0" data-act="pickAvatar"><img src="${u.avatar||IMG.AVATAR}" alt=""></button></div>
<div class="lbl" style="margin-top:44px">Username</div><div class="field"><span class="mut">@</span><input id="e_username" maxlength="20" value="${esc(u.username)}"></div>
<div class="lbl">Display name</div><div class="field"><input id="e_name" maxlength="30" value="${esc(u.name)}"></div>
<div class="lbl" style="display:flex;justify-content:space-between"><span>Bio</span><span id="bc">${u.bio.length} / 160</span></div><div class="field"><textarea id="e_bio" rows="4" maxlength="160">${esc(u.bio)}</textarea></div>
<div class="set" style="padding-left:0"><span class="g">✉ ${esc(u.email)}</span></div><div class="set" style="padding-left:0"><div class="g"><div class="d">Account referrer</div><div class="t">@${esc(u.referrer)}</div></div></div><div class="set" style="padding-left:0"><span class="g">𝕏 ${esc(u.x)}</span><button data-act="rmX" class="dn">${I('x',14)}</button></div>
<button class="set" style="padding-left:0" data-act="addrs"><span class="g"><b>9 addresses ⌄</b></span></button><div id="addrs" style="display:none;font-size:11px;color:var(--mut);word-break:break-all">${Array.from({length:9},(_,i)=>`<div class="rl">0x${hash('a'+i).toString(16).padStart(8,'0')}${hash('b'+i).toString(16).padStart(8,'0')}${hash('c'+i).toString(16).padStart(8,'0')}</div>`).join('')}<div class="dim" style="margin-top:6px">Demo addresses, not real wallets.</div></div>
<button class="btn warn" data-act="exportKeys" style="margin-top:14px">Export keys</button><button class="btn block" id="saveP" style="margin-top:12px;background:#171724" data-act="saveProfile" disabled>Save changes</button><input type="file" id="fpick" accept="image/*" hidden></div>`)}
if(a==='appearance')return sub(t_('appear'),`${tgl('st.sysText','Use system text size','Match text size in your phone settings',S.st.sysText)}${tgl('st.hideSmall','Hide small positions','Hide small positions on your portfolio',S.st.hideSmall)}${tgl('st.haptics','Haptics','Vibration feedback for taps and interactions',S.st.haptics)}${tgl('st.flip','Flip buy and sell buttons','Buy on the left, Sell on the right',S.st.flip)}`);
if(a==='language')return sub(t_('lang'),LANGS.map(([k,n,d])=>`<button class="set" data-act="setLang" data-v="${k}"><span class="g"><div class="t">${n}</div>${d?`<div class="d">${d}</div>`:''}</span>${S.lang===k?I('check',18):''}</button>`).join(''));
if(a==='notifications'){const n=S.nt;if(!b)return sub(t_('notif'),`${tgl('nt.enable','Enable notifications','',n.enable)}${row('settings/notifications/asset','chev','Asset type',n.asset).replace(/<span class="lead">.*?<\/span>/,'')}${row('settings/notifications/price','chev','Price alerts',n.price?'On':'Off').replace(/<span class="lead">.*?<\/span>/,'')}${row('settings/notifications/following','chev','Following activity','Manage','Buys and sells from traders you follow').replace(/<span class="lead">.*?<\/span>/,'')}${tgl('nt.trending','Trending activity','Multiple users trading a token on '+BRAND,n.trending)}${tgl('nt.top',"Top traders' activity",'Large trades from top traders',n.top)}${tgl('nt.ann','Announcements','New features, market news, etc.',n.ann)}${tgl('nt.fol','New followers','',n.fol)}${tgl('nt.ref','Referrals','When someone uses your referral code',n.ref)}`);
if(b==='asset')return sub('Asset type',[['All','Tokens and perps'],['Tokens',''],['Perps','']].map(([k,d])=>`<button class="set" data-act="setv" data-k="nt.asset" data-v="${k}"><span class="g"><div class="t">${k}</div>${d?`<div class="d">${d}</div>`:''}</span>${n.asset===k?I('check',18):''}</button>`).join(''));
if(b==='price')return sub('Price alerts',tgl('nt.price','My holdings','',n.price));
if(b==='following')return sub('Following activity',`${tgl('nt.pause','Pause notifications','',n.pause)}<div class="pad"><h3 style="margin:18px 0 4px;font-size:16px">Minimum size</h3><div class="mut" style="font-size:12px;margin:10px 0 6px">Token trade size</div><div class="grp">${[100,500,1000].map(v=>`<button class="opt ${n.tokMin===v?'on':''}" data-act="setv" data-k="nt.tokMin" data-v="${v}" data-num="1">$${nf(v,0)}</button>`).join('')}<button class="opt" data-act="customMin" data-k="nt.tokMin">Custom</button></div><div class="mut" style="font-size:12px;margin:14px 0 6px">Perps trade size</div><div class="grp">${[10000,25000,50000].map(v=>`<button class="opt ${n.perpMin===v?'on':''}" data-act="setv" data-k="nt.perpMin" data-v="${v}" data-num="1">$${nf(v,0)}</button>`).join('')}<button class="opt" data-act="customMin" data-k="nt.perpMin">Custom</button></div>
<div style="display:flex;justify-content:space-between;margin-top:22px"><b>Following</b><button style="color:var(--acc2);font-weight:700;font-size:13px" data-act="disableAll">Disable all</button></div><div class="mut" style="font-size:12px;margin:2px 0 8px">Manage alerts and notifications for traders you follow</div>${S.follows.length?S.follows.map(h=>`<div class="rl">${tAv(h,28)}<span style="flex:1;margin-left:10px;font-weight:600">${esc(h)}</span><button class="fl on" data-act="follow" data-h="${esc(h)}">Unfollow</button></div>`).join(''):`<div class="field"><span class="mut">${I('search',15)}</span><input placeholder="Search for a trader you follow" disabled></div>`}</div>`)}
if(a==='security'){if(b==='mfa')return sub('Multi-factor authentication',`<div class="mut" style="padding:0 16px;font-size:13px">Add an extra layer of security for transactions</div>${tgl('st.mfa','Authenticator app','',S.st.mfa)}${tgl('st.passkey','Passkey','Sign in with Touch ID',S.st.passkey)}`);return sub(t_('sec'),`${tgl('st.lock','Screen Lock','Require Touch ID for opening the app',S.st.lock)}<button class="set" data-go="settings/security/mfa"><span class="g"><div class="t">Multi-factor authentication</div><div class="d">Add an extra layer of security for transactions</div></span><span class="r">${S.st.mfa||S.st.passkey?'Enabled':'Not enabled'}</span>${I('chev',15)}</button>`)}
if(a==='legal')return sub(t_('legal'),`${['Terms of Service','Privacy Policy','Token Verification Disclaimer'].map(x=>`<button class="set" data-act="legalDoc" data-v="${x}"><span class="g"><div class="t">${x}</div></span>${I('chev',15)}</button>`).join('')}<div style="text-align:center;padding:18px"><button style="color:var(--warn);font-weight:700" data-act="deleteAcc">Delete account</button></div>`);
if(a==='taxes')return sub(t_('tax'),`<div class="pad"><div class="mut" style="font-size:13px;margin-bottom:10px">Create a free account to begin your 2026 tax report.</div><div class="field"><input id="taxm" type="email" placeholder="Enter your email" value="${esc(S.taxEmail)}"></div><div style="text-align:center;margin-top:40vh;color:var(--mut2);font-size:12px">Powered by Demo Tax Partner</div><button class="btn block" id="taxb" style="background:#171724;margin-top:10px" data-act="taxGo">Create account</button></div>`);
if(a==='help')return sub(t_('help'),FAQ.map(([q,an],i)=>`<div class="faq"><b data-act="faq" data-v="${i}">${q}<span>${UI.openFaq===i?'−':'+'}</span></b>${UI.openFaq===i?`<p>${an}</p>`:''}</div>`).join('')+`<div class="pad" style="margin-top:16px"><button class="btn pri block" data-act="contact">Contact support</button></div>`);
return pgSettings([])}
/* ---------- token detail page ---------- */
Object.assign(UI,{tf:null,tTab:'holders',tType:'candle',tHold:false,tThes:true,txOpen:true,abTf:'1H'});
const TFS=['LIVE','1H','4H','1D','7D','ALL'];
const TFM={LIVE:1,'1H':3,'4H':6,'1D':12,'7D':25,ALL:60};
function candles(t,tf){t._c=t._c||{};const key=tf;if(t._c[key])return t._c[key];const r=rng(hash(t.id+tf));const N=40;const cs=[];
if(t.dead){const lv=[];let cur=t.p*(120+r()*160);for(let i=0;i<N;i++){if(i<7)cur*=.5+r()*.2;else if(i<N*.65&&r()<.2)cur*=.45+r()*.3;if(i>=N*.68)cur=t.p;lv.push(Math.max(cur,t.p))}lv[N-1]=t.p;
for(let i=0;i<N;i++){const o=i?lv[i-1]:lv[0]*1.15,c=lv[i];const flat=o===c&&c===t.p;cs.push({o,c,h:flat?c:Math.max(o,c)*(1+r()*.05),l:flat?c:Math.min(o,c)*(1-r()*.03)})}}
else{const v=t.vola*Math.sqrt(TFM[tf])*1.6;const cl=new Array(N);cl[N-1]=t.p0;const dr=(t.chg>0?-1:1)*.0006*Math.sqrt(TFM[tf]);for(let i=N-1;i>0;i--)cl[i-1]=Math.max(cl[i]/(1+(r()-.5)*2*v+dr),1e-12);
for(let i=0;i<N;i++){const o=i?cl[i-1]:cl[0]/(1+(r()-.5)*v),c=cl[i];cs.push({o,c,h:Math.max(o,c)*(1+r()*v*.6),l:Math.min(o,c)*(1-r()*v*.6)})}}
return t._c[key]=cs}
const entryPx=(p,t)=>p.kind==='token'?t.p*((p.entryMC||t.mc)/t.mc):p.entry;
function chartHTML(t){let tf=UI.tf||(t.dead?'ALL':'LIVE');if(t.dead&&tf==='LIVE')tf='ALL';const cs=candles(t,tf).map(c=>({...c}));
if(!t.dead){const l=cs[cs.length-1];l.c=t.p;l.h=Math.max(l.h,t.p);l.l=Math.min(l.l,t.p)}
const pos=S.pos.find(p=>p.open&&p.id===t.id);const ep=pos?entryPx(pos,t):null;
let lo=Math.min(...cs.map(c=>c.l),ep??Infinity,t.p),hi=Math.max(...cs.map(c=>c.h),ep??-Infinity,t.p);if(hi===lo){hi*=1.01;lo*=.99}
const H=300,pd=22,Y=v=>pd+(1-(v-lo)/(hi-lo))*(H-pd*2),n=cs.length,sl=400/n,bw=sl*.55;let g='';
if(UI.tType==='line'){g=`<polyline fill="none" stroke="${cs[n-1].c>=cs[0].o?'#2fe27a':'#ff5a3c'}" stroke-width="2" vector-effect="non-scaling-stroke" points="${cs.map((c,i)=>(i*sl+sl/2).toFixed(1)+','+Y(c.c).toFixed(1)).join(' ')}"/>`}
else cs.forEach((c,i)=>{const x=i*sl+sl/2,col=c.c>=c.o?'#2fe27a':'#ff5a3c';if(c.h===c.l)g+=`<line x1="${x-sl/2}" x2="${x+sl/2}" y1="${Y(c.c)}" y2="${Y(c.c)}" stroke="${t.dead?'#2fe27a':col}" stroke-width="1" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>`;else g+=`<line x1="${x}" x2="${x}" y1="${Y(c.h)}" y2="${Y(c.l)}" stroke="${col}" stroke-width="1.2" vector-effect="non-scaling-stroke"/><rect x="${x-bw/2}" y="${Math.min(Y(c.o),Y(c.c))}" width="${bw}" height="${Math.max(1.5,Math.abs(Y(c.o)-Y(c.c)))}" fill="${col}"/>`});
const up=t.chg>=0,cc=up?'#2fe27a':'#ff5a3c',yc=Y(t.p);
const el=ep!=null?`<line x1="0" x2="400" y1="${Y(ep)}" y2="${Y(ep)}" stroke="${t.p>=ep?'#2fe27a':'#ff5a3c'}" stroke-width="1" stroke-dasharray="4 3" vector-effect="non-scaling-stroke"/>`:'';
const lab=t.kind==='perp'?fmtP(t.p):'$'+abbr(t.mc);
return `<svg viewBox="0 0 400 ${H}" preserveAspectRatio="none">${g}${el}<line x1="0" x2="400" y1="${yc}" y2="${yc}" stroke="${cc}" stroke-width="1" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/></svg>${ep!=null?`<span class="elab" style="top:calc(${Y(ep)/H*100}% - 22px)">⌃ Avg. entry</span>`:''}<span class="ptag ${up?'g':'r'}" style="top:${yc/H*100}%">${lab}</span>`}
const tcText=t=>{const d=t.p-t.base;return `${d<0?'▼':'▲'} ${fmtP(Math.abs(d))} (${Math.abs(t.chg).toFixed(2)}%)`};
const CMT=['Is this done','Rug??','rocket','next stage is 1M','good entry point','entry now','So many buys and sells','LFG','holding','sold the top'];
function tokPosts(t){const r=rng(hash('p'+t.id));return Array.from({length:7},(_,i)=>{const n=TN[17+Math.floor(r()*(TN.length-18))];const neg=t.dead||r()<.4;const pc=neg?(t.dead?85+r()*14:r()*40):r()*90;const amt=Math.exp(rnd(Math.log(15),Math.log(150)));const mcAt=t.dead?t.mc*(40+r()*70):t.mc*(.6+r()*.7);return {n,type:'Closed',pnl:(neg?-1:1)*amt*pc/100,pc:neg?-pc:pc,txt:CMT[Math.floor(r()*CMT.length)],date:'Oct '+(20+Math.floor(r()*9)),mc:mcAt,likes:Math.floor(r()*3),older:Math.floor(r()*3)}})}
const thesis=id=>S.thesis[id]||[];
function thesisRow(th){return `<div class="fi" style="border:0;padding:8px 0">${tAv(S.user.username,28)}<div class="b"><div class="top">${esc(S.user.username)}<span class="ago">${th.lbl||dt(th.ts)} at $${abbr(th.mc)} MC</span></div><div style="font-size:15px">${esc(th.txt)}</div><div class="tg" style="margin-top:8px;gap:16px"><button data-act="likeTh" data-id="${esc(th.id)}" data-i="${th.i}" style="display:flex;gap:5px;align-items:center;${th.liked?'color:#6674ff':''}">${I('heart',17)} ${th.likes}</button><span style="display:flex;gap:5px;align-items:center">${I('eye',17)} ${th.views}</span><button data-act="shareTh">${I('share',17)}</button></div></div></div>`}
P.eye='<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>';
function txList(t){const a=S.act.filter(x=>x.id===t.id);if(!a.length)return '';return `<div class="ph" style="padding-top:22px"><button data-act="txOpen" style="display:flex;gap:6px;align-items:center;font-size:18px;font-weight:700">${a.length} transaction${a.length>1?'s':''} <span class="mut" style="transform:rotate(${UI.txOpen?0:180}deg)">${I('up',16)}</span></button><span class="mut">${I('filt',17)}</span></div>${UI.txOpen?a.map(x=>{const buy=x.type==='Buy'||x.type==='Opened';const atT=x.ak==='mc'?'$'+abbr(x.at)+' MC':fmtP(x.at);return `<div style="padding:8px 16px"><div style="display:flex;justify-content:space-between"><b class="${buy?'up':'dn'}" style="font-size:19px;font-weight:700">${x.type==='Buy'?'Bought':x.type==='Sell'?'Sold':x.type}</b><b style="font-size:19px">${buy?'+':'-'}$${nf(x.amt)}</b></div><div class="mut" style="display:flex;justify-content:space-between;font-size:12px;margin-top:3px"><span>${x.lbl||dt(x.ts)}</span><span>${x.qty?abbr(x.qty)+' at ':''}${atT}</span></div></div>`}).join(''):''}`}
function holdersTab(t){if(t.dead||t.kind==='perp')return emptyBox(t.kind==='perp'?'Perp markets have no holders.':'No holders yet.');
const r=rng(hash('h'+t.id));let hs=Array.from({length:8},(_,i)=>{const n=TN[17+Math.floor(r()*(TN.length-18))];return {n,pc:Math.max(.2,(8-i)*r()*1.2),v:t.mc*(8-i)*r()*.012}});const held=S.pos.find(p=>p.open&&p.id===t.id);if(held)hs.push({n:S.user.username,pc:held.qty/(t.mc/t.p)*100,v:val(held),me:1});if(UI.tHold)hs=hs.filter(h=>h.me||S.follows.includes(h.n));
return `<div style="padding:8px 16px"><div class="tg"><button class="sw ${UI.tHold?'on':''}" style="width:42px;height:24px" data-act="tHold"></button>Following</div></div>`+(hs.length?`<div class="list">${hs.map((h,i)=>`<div class="row" data-act="trader" data-h="${esc(h.n)}"><span class="rk">${i+1}.</span>${tAv(h.n,36)}<div class="mid"><div class="nm">${esc(h.n)}${h.me?'<span class="pill">You</span>':''}</div><div class="sub">${h.pc.toFixed(2)}% supply</div></div><div class="rt"><div class="px">$${abbr(h.v)}</div></div></div>`).join('')}</div>`:emptyBox('No holders you follow.'))}
function feedTab(t){const ps=[...thesis(t.id).map((x,i)=>({me:1,n:S.user.username,pnl:null,txt:x.txt,date:x.lbl||dt(x.ts),mc:x.mc,likes:x.likes,type:'Thesis'})),...tokPosts(t)];const list=UI.tThes?ps:ps;
return `<div style="padding:8px 16px"><div class="tg"><span>Thesis only</span><button class="sw ${UI.tThes?'on':''}" style="width:42px;height:24px" data-act="tThes"></button></div></div>`+list.map(p=>`<div class="fi" style="align-items:flex-start">${tAv(p.n,34)}<div class="b"><div class="top">${esc(p.n)}${chipT(p.type)}<span class="ago">${p.date} at $${abbr(p.mc)} MC</span></div>${p.pnl!=null?`<div class="ln" style="margin-bottom:6px">${ico(t,22)}<b class="${p.pnl<0?'dn':'up'}">${sgn(p.pnl)}</b><span class="${p.pc<0?'dn':'up'}" style="font-size:12px">(${pct(p.pc)})</span></div>`:''}<div style="font-size:14px">${esc(p.txt)}</div><div class="tg" style="margin-top:6px">${I('heart',16)} ${p.likes}</div></div></div>`).join('')}
function aboutTab(t){const h=hash(t.id),dead=t.dead,perp=t.kind==='perp';const mk=(a,b)=>{const s=a+b||1;return `<div style="display:flex;gap:6px;margin:6px 0"><div style="flex:${a||1};height:3px;background:var(--up);border-radius:2px"></div><div style="flex:${b||1};height:3px;background:var(--dn);border-radius:2px"></div></div>`};
const buys=dead?0:h%90+10,sells=dead?0:(h>>3)%70+5,vb=dead?0:buys*(h%40+10),vs=dead?0:sells*(h%30+8),bu=Math.ceil(buys*.8),se=Math.ceil(sells*.8);const sup=t.mc/t.p;
const st=(a,b)=>`<div class="rl" style="border:0"><span class="mut">${a}</span><b>${b}</b></div>`;
return `<div class="pad"><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px"><h3 style="margin:0;font-size:19px;text-align:left">Description</h3><a data-act="srchX" style="display:flex;gap:5px;align-items:center;font-weight:700;font-size:13px;cursor:pointer">${I('search',15)} Search on X</a></div><p class="mut" style="margin:10px 0">${esc(t.name)}</p><div class="hs" style="padding:0"><button class="btn" style="display:flex;gap:8px;align-items:center" data-act="srchX">${I('globe',18)} Website</button><button class="btn" data-act="srchX">𝕏 X/Twitter</button></div>
${perp?'':`<div style="display:flex;justify-content:space-between;align-items:center;margin-top:28px"><h3 style="margin:0;font-size:19px">Transactions</h3><div class="sw2">${['5M','1H','1D'].map(x=>`<button class="${UI.abTf===x?'on':''}" data-act="abTf" data-v="${x}">${x}</button>`).join('')}</div></div>
<div style="display:flex;justify-content:space-between;font-size:17px;margin-top:14px"><span>${buys} buys</span><span>${sells} sells</span></div>${mk(buys,sells)}<div style="display:flex;justify-content:space-between;font-size:17px;margin-top:12px"><span>$${abbr(vb)} vol.</span><span>$${abbr(vs)} vol.</span></div>${mk(vb,vs)}<div style="display:flex;justify-content:space-between;font-size:17px;margin-top:12px"><span>${bu} buyers</span><span>${se} sellers</span></div>${mk(bu,se)}
<h3 style="margin:28px 0 8px;font-size:19px;text-align:left">Holders</h3>${st('Number of holders',dead?530:h%900+40)}${st('Top 10 Holding',((h%300)/100+1).toFixed(2)+'%')}<button class="opr" style="margin-top:12px" data-act="srchX"><span style="font-size:18px">🪪</span><span class="g"><div class="t">On the ${esc(t.sym)} team?</div><div class="d">Apply for a team tag so holders see your updates</div></span>${I('chev',16)}</button>`}
<h3 style="margin:28px 0 8px;font-size:19px;text-align:left">Stats</h3>${perp?st('Max leverage',t.lev+'x')+st('24h volume','$'+abbr(t.vol))+st('Funding (1h)',(h%9/1000).toFixed(4)+'%'):st('Market cap','$'+abbr(t.mc))+st('24h volume',dead?'$0':'$'+abbr(t.vol))+st('Liquidity','$'+abbr(Math.max(t.mc*.96,1000)))+st('Supply',abbr(sup))+st('Created',(h%60+3)+' days ago')+st('Launchpad','Pump.fun')+st('Network','Solana')+`<div class="rl" style="border:0"><span class="mut">Contract address</span><b data-act="copyAddr" data-v="F${h.toString(16)}o...pump" style="cursor:pointer">F${h.toString(16).slice(0,5)}...pump ${I('copy',13)}</b></div>`}</div>`}
function pgToken(r){const id=decodeURIComponent(r[0]||'');const t=DB[id];if(!t)return `<div class="page">${emptyBox('Token not found.')}</div>`;
const perp=t.kind==='perp',dead=t.dead;const held=S.pos.filter(p=>p.open&&p.id===id);const pos=held[0];
let card='';
if(held.length&&!perp){const v=val(pos),c=pos.invested,pnl=v-c,pc=pnl/c*100;card=`<div style="margin:6px 16px 0;border:1px solid #1f1f30;border-radius:18px;background:var(--bg2)"><div style="padding:16px"><div style="display:flex;justify-content:space-between"><b style="font-size:27px" data-pv="${pos.uid}">${usd(v)}</b><b class="${pnl<0?'dn':'up'}" style="font-size:27px">${pnl<0?'-':'+'}$${nf(Math.abs(pnl))}</b></div><div style="display:flex;justify-content:space-between;margin-top:6px" class="mut"><span>${abbr(pos.qty)} ${esc(t.sym)}</span><span class="${pnl<0?'dn':'up'}">${pnl<0?'▼':'▲'} ${Math.abs(pc).toFixed(2)}%</span></div><div style="border-top:1px dashed #262636;margin:14px 0 10px"></div><div style="display:flex;justify-content:space-between;font-size:14px"><span class="mut">Invested <b style="color:#fff;margin-left:8px">${usd(c)}</b></span><span class="mut">Avg. entry <b style="color:#fff;margin-left:8px">$${abbr(pos.entryMC||t.mc)} MC</b></span></div></div><button data-act="tShare" style="width:100%;padding:12px;background:#12121e;border-radius:0 0 18px 18px;font-weight:700;display:flex;gap:8px;justify-content:center;align-items:center">${I('share',17)} Share</button></div>`}
else if(held.length&&perp)card=`<div class="pad">${held.map(p=>{const v=val(p),pc=(v/p.margin-1)*100;return `<div class="cardx" style="display:flex;justify-content:space-between;align-items:center"><span>${levChip(p.side,p.lev)} <span class="mut">${usd(p.margin)} margin</span></span><b class="${pc<0?'dn':'up'}"><span data-pv="${p.uid}">${usd(v)}</span> (${pct(pc)})</b></div>`}).join('')}</div>`;
const th=thesis(id).map((x,i)=>thesisRow({...x,id,i})).join('');
const tf=UI.tf||(dead?'ALL':'LIVE');const cash=perp?S.cash.perps:S.cash.tokens;
const warn=dead?'Low liquidity + 1':t.vf?'':(hash(id)%2?'Large holdings from insiders + 2':'Low liquidity + 1');
const tabBody=perp?aboutTab(t):UI.tTab==='holders'?holdersTab(t):UI.tTab==='feed'?feedTab(t):aboutTab(t);
return `<div class="page tokpg"><div class="thead"><button class="ibtn" data-act="tback">${I('back',22)}</button>${ico(t,44)}<div style="flex:1;min-width:0"><div style="display:flex;align-items:center;gap:6px;font-size:19px;font-weight:700">${esc(t.sym)}${perp?`<span class="tag">${t.lev}x</span>`:'<span class="mut" style="font-size:14px">≡ 💊</span>'}${dead?'<span class="tp Sell">RUGGED</span>':''}</div><div class="mut" style="font-size:13px">${esc(t.name)} ${I('copy',12)}</div></div><button class="ibtn" data-act="tHist">${I('hist',21)}</button><button class="ibtn" data-act="wlist" data-id="${esc(id)}" style="${S.watch.includes(id)?'color:#f2c94c':''}">${I('star',21)}</button><button class="ibtn" data-act="tShare">${I('share',21)}</button></div>
<div style="display:flex;justify-content:space-between;padding:6px 16px 0"><div><div style="font-size:30px;font-weight:700;letter-spacing:-.5px" data-p="${esc(id)}">${fmtP(t.p)}</div><div class="${t.chg>=0?'up':'dn'}" style="font-size:14px;margin-top:2px" data-tc="${esc(id)}">${tcText(t)}</div></div><div style="text-align:right;font-size:12px" class="mut"><b style="font-size:20px;color:#fff" ${perp?'':`data-mcb="${esc(id)}"`}>${perp?'$'+abbr(t.vol):'$'+abbr(t.mc)}</b><br>${perp?'24h volume':'Market cap'}</div></div>
${dead?'<div class="banner" style="margin-top:12px;color:#ffb4a6;background:#2a1613">'+I('info',16)+'<span><b style="color:#ff7a5c">Token rugged / dead.</b> Liquidity was removed, so the chart is frozen and buying is disabled.</span></div>':''}
<div class="tchart" id="tchart">${chartHTML(t)}</div>
<div class="tfrow">${TFS.map(x=>`<button class="${tf===x?'on':''}" ${dead&&x==='LIVE'?'disabled':''} data-act="tTf" data-v="${x}">${x}${x==='LIVE'&&!dead?'<i class="ld"></i>':''}</button>`).join('')}<span class="vr"></span><button data-act="tType" style="color:var(--up)">${I(UI.tType==='line'?'grid':'sort',19)}</button></div>
${card}
<div style="padding:12px 16px 0"><button style="display:flex;gap:10px;align-items:center;color:var(--acc2);font-weight:700" data-act="thesisSheet"><span style="width:26px;height:26px;border-radius:50%;border:1px solid #2a2f6a;display:grid;place-items:center">${I('plus',14)}</span> Update thesis</button>${th}</div>
${perp?'':txList(t)}
<div class="tabs" style="margin-top:22px;${perp?'display:none':''}">${[['holders','Holders'],['feed','Feed'],['about','About']].map(([k,l])=>`<button class="${UI.tTab===k?'on':''}" data-act="tTab" data-v="${k}">${l}</button>`).join('')}</div>
<div style="padding-bottom:20px">${tabBody}</div>
<div class="tbar">${UI.qt&&!perp?qtPanel(t,cash):`${warn?`<div class="twarn">${I('warn',16)}<b>Warning: ${warn}</b><button data-act="tInfo" class="mut">${I('info',15)}</button></div>`:''}<div class="tbtns"><button class="tb sell" data-act="tSell" ${held.length?'':'disabled'}>${perp?'Close':'Sell'}</button><button class="tb buy" data-act="tBuy" ${dead?'disabled':''}>${dead?'Buying disabled':cash<1?(perp?'Deposit to trade':'Deposit to buy'):(perp?'Open position':'Buy')}</button><button class="tb bolt" data-act="tQuick" aria-label="Quick trades">${I('bolt',22)}</button></div>`}</div></div>`}
P.warn='<path d="M12 3 2 20h20z"/><path d="M12 10v4M12 17v.1"/>';
const fv=v=>'$'+(+v).toString();
function qtPanel(t,cash){const q=S.qt;return `<div class="qt"><div class="qh"><span>${I('bolt',18)} Quick Trades</span><button class="gear" data-act="qtSet" aria-label="Quick trade settings">${I('sl',20)}</button></div><div class="qr"><b class="up">Buy</b>${q.buy.map(v=>`<button class="qb" data-act="qtBuy" data-v="${v}" ${t.dead?'disabled':''}>${fv(v)}</button>`).join('')}</div><div class="qr"><b class="dn">Sell</b>${q.sell.map(v=>`<button class="qb s" data-act="qtSell" data-v="${v}">${v}%</button>`).join('')}</div><div class="qf"><span>Cash ${usd(cash,cash%1?2:0)}</span><span class="sl">${I('bolt',15)} ${q.auto?'Auto':q.slip+'%'}</span></div><button class="btn block" style="background:#14141f" data-act="qtClose">Close</button></div>`}
function openTrade(id,mode){if(!DB[id])return;const t=DB[id];UI.tr={id,mode:mode||'buy',amt:'',pct:100,side:'long',lev:Math.min(10,t.lev||1),err:''};sheet(tradeHTML())}

const PAGES={token:pgToken,home:pgHome,search:pgSearch,feed:pgFeed,leaderboard:pgLb,profile:pgProfile,rewards:pgRewards,settings:pgSettings};
TX.en.rewards='Rewards';
/* ---------- sheets content ---------- */
function depositSheet(){sheet(`<h3>Deposit with</h3><div class="sd">Demo only: no real money moves</div>${[['Bank Account','bank','Bank transfer · usually 2-3 business days','<span class="pill">New</span><span class="pill g">Lowest fees</span>'],['Crypto','grid','Receive USDC from a crypto wallet',''],['Debit','card','Deposit cash with a debit card',''],['Exchanges and apps','wallet','Cash App, Coinbase, Binance','']].map(([n,ic,d,tg])=>`<button class="opr" data-act="depAmt" data-v="${n}"><span class="g"><div class="t">${n}${tg}</div><div class="d">${d}</div></span>${I(ic,22)}</button>`).join('')}<button class="btn block" style="background:transparent;color:var(--acc2)" data-act="wdSheet">Withdraw instead</button>`)}
function amtSheet(title,sub_,btn,act,data,chips){sheet(`<h3>${title}</h3><div class="sd">${sub_}</div>${data.pre||''}<div class="field"><span class="mut">$</span><input id="amtin" inputmode="decimal" placeholder="0.00" autofocus></div><div class="q">${chips.map(c=>`<button data-act="chipAmt" data-v="${c}">$${c}</button>`).join('')}</div><div class="err" id="amte"></div><button class="cta acc" data-act="${act}" data-v="${esc(data.v||'')}">${btn}</button>`);setTimeout(()=>$('#amtin')?.focus(),50)}
function wdSheet(){sheet(`<h3>Choose withdraw method</h3><div class="sd">Available cash: ${usd(S.cash.tokens)}</div>${[['Bank account (US only)','Withdraw US dollars via ACH','bank'],['Crypto wallet','Withdraw USDC to a supported network','wallet'],['Finance apps','PayPal, Venmo, Robinhood, Wealthsimple, etc.','grid']].map(([n,d,i])=>`<button class="opr" data-act="wdAmt" data-v="${n}"><span class="g"><div class="t">${n}</div><div class="d">${d}</div></span>${I(i,22)}</button>`).join('')}`)}
function cashSheet(){sheet(`<div style="text-align:center;color:var(--mut);font-size:12px">Total cash</div><div style="text-align:center;font-size:30px;font-weight:700;margin:2px 0 12px" data-cashs>${usd(S.cash.tokens+S.cash.perps,0)}</div><div class="cardx" style="border:1px solid var(--line)"><div class="rl"><span>Tokens cash</span><b>${usd(S.cash.tokens)}</b></div><div class="rl"><span>Perps cash</span><b>${usd(S.cash.perps)}</b></div><button class="btn block" style="background:#1a1a28;margin-top:8px" data-act="transferSheet">${I('swap',16)} Transfer cash</button></div><div style="height:10px"></div><button class="opr" data-act="deposit"><span class="g"><div class="t">Deposit</div><div class="d">Crypto, Google Pay, Debit card, or bank account</div></span>${I('plus',20)}</button><button class="opr" data-act="wdSheet"><span class="g"><div class="t">Withdraw</div><div class="d">Bank account or crypto wallet</div></span>${I('up',20)}</button><button class="opr" data-act="sendSheet"><span class="g"><div class="t">Send</div><div class="d">Transfer cash to anyone on ${BRAND}</div></span>${I('send',20)}</button><div style="text-align:center"><button style="color:var(--acc2);font-weight:700;padding:8px" data-act="xferHist">${I('hist',15)} View transfer history</button></div>`)}
function xferHist(){sheet(`<h3>Transfer history</h3><div class="sd">Deposits, withdrawals, sends and transfers</div>${S.xfer.length?S.xfer.map(x=>`<div class="rl"><span><b>${x.type}</b><div class="mut" style="font-size:11px">${esc(x.via||'')} · ${dt(x.ts)}</div></span><b class="${x.amt<0?'dn':'up'}">${sgn(x.amt)}</b></div>`).join(''):emptyBox('No transfers yet.')}`)}
function transferSheet(dir){dir=dir||'t2p';sheet(`<h3>Transfer cash</h3><div class="sd">Move cash between your Tokens and Perps balances</div><div class="seg"><button class="${dir==='t2p'?'on acc':''}" data-act="transferSheet" data-v="t2p">Tokens → Perps</button><button class="${dir==='p2t'?'on acc':''}" data-act="transferSheet" data-v="p2t">Perps → Tokens</button></div><div class="nfo"><span>Available</span><b>${usd(dir==='t2p'?S.cash.tokens:S.cash.perps)}</b></div><div class="field"><span class="mut">$</span><input id="amtin" inputmode="decimal" placeholder="0.00"></div><div class="err" id="amte"></div><button class="cta acc" data-act="doTransfer" data-v="${dir}">Transfer</button>`)}
function sendSheet(){sheet(`<h3>Send cash</h3><div class="sd">Available: ${usd(S.cash.tokens)}</div><div class="field"><span class="mut">@</span><input id="sendto" placeholder="username"></div><div class="field"><span class="mut">$</span><input id="amtin" inputmode="decimal" placeholder="0.00"></div><div class="err" id="amte"></div><button class="cta acc" data-act="doSend">Send</button>`)}
function bellSheet(){S.notifs.forEach(n=>n.u=0);save();sheet(`<h3>Notifications</h3><div class="sd">${S.nt.enable?'You are up to date':'Notifications are turned off'}</div>${S.notifs.map(n=>`<div class="nrow"><span style="flex:1">${esc(n.t)}<div class="mut" style="font-size:11px;margin-top:2px">${ago(n.ts)} ago</div></span></div>`).join('')}`);if(location.hash.includes('home')||!location.hash)render()}
function traderSheet(h){const t=TR[h]||{name:h,followers:S.followers,pnl:0,win:0};const me=h===S.user.username;const pos=ALL.filter(x=>x.kind==='token').slice(hash(h)%40,hash(h)%40+3);
sheet(`<div style="display:flex;align-items:center;gap:12px">${tAv(h,52)}<div style="flex:1"><b style="font-size:18px">${esc(h)}</b><div class="mut" style="font-size:12px">@${esc(h.replace(/\s/g,''))}</div></div>${me?'':`<button class="fl ${S.follows.includes(h)?'on':''}" data-act="follow" data-h="${esc(h)}">${S.follows.includes(h)?'Following':'Follow'}</button>`}</div><div class="stats"><div><small>Followers</small><b>${nf(me?S.followers:t.followers,0)}</b></div><div><small>24h PnL</small><b class="up">${sgn(me?d24():t.pnl)}</b></div><div><small>Win rate</small><b>${t.win||'-'}%</b></div></div><div class="mut" style="font-size:12px;margin-bottom:4px">Recent positions</div>${me?'<div class="mut">See your Profile.</div>':pos.map(x=>`<div class="row" data-act="token" data-id="${esc(x.id)}">${ico(x,34)}<div class="mid"><div class="nm">${esc(x.sym)}</div></div><div class="rt"><div class="px" data-p="${esc(x.id)}">${fmtP(x.p)}</div></div></div>`).join('')}`)}
/* trade sheet */
function sparkSvg(t){const a=t.h,mn=Math.min(...a),mx=Math.max(...a),w=400,h=96;const up=a[a.length-1]>=a[0];const pts=a.map((v,i)=>[i/(a.length-1)*w,6+(h-12)-(mx===mn?.5:(v-mn)/(mx-mn))*(h-12)]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');const c=up?'#2fe27a':'#ff5a3c';return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${d}L${w} ${h}L0 ${h}Z" fill="${c}" fill-opacity=".1"/><path d="${d}" fill="none" stroke="${c}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function openToken(id){if(!DB[id]){toast('Details not available for this token.');return}UI.tf=null;UI.tTab='holders';UI.qt=false;go('token/'+encodeURIComponent(id))}
function tradeHTML(){const tr=UI.tr,t=DB[tr.id],perp=t.kind==='perp';const held=S.pos.filter(p=>p.open&&p.id===t.id);const hv=held.reduce((a,p)=>a+val(p),0);const hc=held.reduce((a,p)=>a+cost(p),0);
const modes=[['sell',perp?'Close':'Sell'],['buy',perp?'Open':'Buy']];if(S.st.flip)modes.reverse();
let body='';const cash=perp?S.cash.perps:S.cash.tokens;
if(t.dead&&tr.mode==='buy')body='<div class="mut" style="padding:14px 0">Buying is disabled: this token was rugged and has no liquidity.</div>';else if(tr.mode==='buy'){const a=parseFloat(tr.amt)||0;
if(perp)body=`<div class="seg" style="margin-top:10px"><button class="${tr.side==='long'?'on buy':''}" data-act="tside" data-v="long">Long</button><button class="${tr.side==='short'?'on sell':''}" data-act="tside" data-v="short">Short</button></div><div class="nfo"><span>Leverage</span><b id="levv">${tr.lev}x</b></div><input type="range" id="lev" min="1" max="${t.lev}" value="${tr.lev}">`;
body+=`<div class="field" style="margin-top:10px"><span class="mut">$</span><input id="tamt" inputmode="decimal" placeholder="${perp?'Margin':'Amount'}" value="${esc(tr.amt)}"></div><div class="q">${[1,5,25,100].map(v=>`<button data-act="tchip" data-v="${v}">$${v}</button>`).join('')}<button data-act="tchip" data-v="max">Max</button></div><div class="nfo"><span>${perp?'Perps cash':'Cash'}</span><b>${usd(cash)}</b></div><div class="nfo"><span id="est1">${estTxt(t,tr,a)}</span><span></span></div>`;}
else if(perp){body=held.length?held.map(p=>{const v=val(p),pc=(v/p.margin-1)*100;return `<div class="rl"><span>${levChip(p.side,p.lev)} <span class="mut" style="margin-left:6px">${usd(p.margin)} margin</span></span><span><b class="${pc<0?'dn':'up'}">${usd(v)} (${pct(pc)})</b> <button class="fl" style="margin-left:8px" data-act="tclose" data-uid="${p.uid}">Close</button></span></div>`}).join(''):'<div class="mut" style="padding:14px 0">You have no open position in this market.</div>'}
else{body=held.length?`<div class="q">${[25,50,75,100].map(v=>`<button class="${tr.pct===v?'on':''}" data-act="tpct" data-v="${v}">${v}%</button>`).join('')}</div><div class="nfo"><span>You receive ≈</span><b id="est1">${usd(hv*tr.pct/100,4>hv?4:2)}</b></div>`:'<div class="mut" style="padding:14px 0">You don\'t hold this token yet.</div>'}
const showCta=(tr.mode==='buy'&&!t.dead)||(tr.mode==='sell'&&!perp&&held.length);
const ctaT=tr.mode==='buy'?(perp?`Open ${tr.lev}x ${tr.side==='long'?'Long':'Short'}`:`Buy ${esc(t.sym)}`):`Sell ${tr.pct}%`;
return `<div style="display:flex;align-items:center;gap:12px">${ico(t,44)}<div style="flex:1"><b style="font-size:18px">${esc(t.sym)}${perp?`<span class="tag">${t.lev}x</span>`:''}</b><div class="mut" style="font-size:12px">${esc(t.name)}${perp?' · Perp':''}</div></div>${perp?'':`<button class="ibtn" data-act="twatch" aria-label="Watchlist" style="${S.watch.includes(t.id)?'color:#f2c94c':''}">${I('star',20)}</button>`}<button class="ibtn" data-act="closeSheet">${I('x',20)}</button></div>
<div style="margin-top:12px"><span style="font-size:28px;font-weight:800" data-p="${esc(t.id)}">${fmtP(t.p)}</span> <span class="ch ${t.chg>=0?'up':'dn'}" data-c="${esc(t.id)}" style="font-weight:700;font-size:13px">${pct(t.chg)}</span></div>${t.dead?'<div class="spark mut" style="display:grid;place-items:center;font-size:12px">Chart halted: token rugged</div>':`<div class="spark" data-spark="${esc(t.id)}">${sparkSvg(t)}</div>`}
<div class="stats"><div><small>${perp?'Max leverage':'Market cap'}</small><b ${perp?'':`data-mc="${esc(t.id)}"`}>${perp?t.lev+'x':'$'+abbr(t.mc)+' MC'}</b></div><div><small>24h volume</small><b>$${abbr(t.vol)}</b></div><div><small>Your position</small><b>${held.length?usd(hv):'—'}</b></div></div>
<div class="seg">${modes.map(([k,l])=>`<button class="${tr.mode===k?'on '+(k==='buy'?'buy':'sell'):''}" data-act="tmode" data-v="${k}">${l}</button>`).join('')}</div>${body}<div class="err" id="terr">${tr.err||''}</div>${showCta?`<button class="cta ${tr.mode==='buy'?'buy':'sell'}" data-act="texec">${ctaT}</button>`:''}`}
function estTxt(t,tr,a){if(t.kind==='perp'){const e=t.p,l=tr.lev,d=tr.side==='long'?1:-1;const liq=e*(1-d*.95/l);return `Size ${usd(a*l)} · Liq. ≈ ${fmtP(liq)}`}return a>0?`≈ ${abbr(a/t.p)} ${esc(t.sym)}`:''}
