doDeposit(el){const a=parseFloat($('#amtin').value);if(!(a>0)){$('#amte').textContent='Enter a valid amount.';return}S.cash.tokens+=a;S.xfer.unshift({type:'Deposit',amt:a,via:el.dataset.v,ts:Date.now()});save();closeSheet();toast(`Deposited ${usd(a)}`);render(true)},
doWithdraw(el){const a=parseFloat($('#amtin').value);if(!(a>0)){$('#amte').textContent='Enter a valid amount.';return}if(a>S.cash.tokens+1e-9){$('#amte').textContent='Amount exceeds available cash.';return}S.cash.tokens-=a;S.xfer.unshift({type:'Withdraw',amt:-a,via:el.dataset.v,ts:Date.now()});save();closeSheet();toast(`Withdrawn ${usd(a)} (demo)`);render(true)},
doTransfer(el){const a=parseFloat($('#amtin').value),d=el.dataset.v;const from=d==='t2p'?'tokens':'perps',to=d==='t2p'?'perps':'tokens';if(!(a>0)){$('#amte').textContent='Enter a valid amount.';return}if(a>S.cash[from]+1e-9){$('#amte').textContent='Not enough cash in source balance.';return}S.cash[from]-=a;S.cash[to]+=a;S.xfer.unshift({type:'Transfer',amt:a,via:from+' → '+to,ts:Date.now()});save();closeSheet();toast(`Moved ${usd(a)} to ${to}`);render(true)},
doSend(){const to=$('#sendto').value.trim().replace(/^@/,''),a=parseFloat($('#amtin').value);if(!to){$('#amte').textContent='Enter a username.';return}if(!(a>0)){$('#amte').textContent='Enter a valid amount.';return}if(a>S.cash.tokens+1e-9){$('#amte').textContent='Not enough cash.';return}S.cash.tokens-=a;S.xfer.unshift({type:'Send',amt:-a,via:'to @'+to,ts:Date.now()});save();closeSheet();toast(`Sent ${usd(a)} to @${to}`);render(true)},
token(el){const id=el.dataset.id;if(id)openToken(id)},
sres(el){const k=el.dataset.k,id=el.dataset.id;S.recents=S.recents.filter(r=>!(r[0]===k&&r[1]===id));S.recents.unshift([k,id]);S.recents=S.recents.slice(0,20);save();if(k==='trader')traderSheet(id);else if(k==='clan'){const c=CLANS.find(x=>x.n===id);sheet(`<div style="display:flex;gap:12px;align-items:center">${ico(id,52,0)}<div><b style="font-size:18px">${esc(id)}</b><div class="mut">${c.m} members</div></div></div><div class="stats"><div><small>24h PnL</small><b class="up">+$${nf(c.p)}</b></div><div><small>Members</small><b>${c.m}</b></div><div><small>Rank</small><b>#${CLANS.indexOf(c)+1}</b></div></div><button class="cta acc" data-act="joinClan" data-id="${esc(id)}">Request to join</button>`)}else openToken(id)},
